469	// 只有成功状态下、且报告通过完整校验时才算拿到可靠的导入结果：
470	// 新增/未导入数量为非负整数；未导入明细是数组，逐条含正整数数据记录编号与
471	// 非空文本原因；明细条数与未导入数量一致。任一不满足都返回 null，
472	// 不用 0、空数组或 undefined 补造一份成功报告。
473	function parseImportReport(data) {
474	  if (!data || typeof data !== "object" || Array.isArray(data)) return null;
475	  const importedCount = data.imported_count;
476	  const failedCount = data.failed_count;
477	  if (!isNonNegativeInt(importedCount) || !isNonNegativeInt(failedCount)) return null;
478	  if (!Array.isArray(data.failures) || data.failures.length !== failedCount) return null;
479	  const failures = [];
480	  for (const item of data.failures) {
481	    if (!item || typeof item !== "object") return null;
482	    if (typeof item.row !== "number" || !Number.isInteger(item.row) || item.row <= 0) return null;
483	    if (typeof item.reason !== "string" || !item.reason.trim()) return null;
484	    failures.push({row: item.row, reason: item.reason});
485	  }
486	  return {importedCount, failedCount, failures};
487	}
