660	def _normalize_set_value(field_name, value):
661	    """校验 set 操作的值并返回最终入库值；非法时抛 BatchUpdateError。
662	
663	    去除前后空白；仅含空白按清空（None）处理；来源/地区/行业保留内部空白与换行；
664	    重要日期非空时须为 YYYY-MM-DD 真实日历日期。
665	    """
666	    if not isinstance(value, str):
667	        raise BatchUpdateError("%s的设置值不是文本" % FIELD_LABELS[field_name])
