678	def batch_update_clients(database, payload):
679	    """执行批量修改，返回 {"updated_count": 去重后的客户数}；非法请求抛 BatchUpdateError。
680	
681	    任一问题都整次拒绝，不写入任何客户。
682	    """
683	    if not isinstance(payload, dict):
684	        raise BatchUpdateError("请求体必须是 JSON 对象")
685	
686	    raw_ids = payload.get("ids")
687	    if not isinstance(raw_ids, list):
688	        raise BatchUpdateError("ids 必须是客户编号数组")
689	    if not raw_ids:
690	        raise BatchUpdateError("未选择客户：请先勾选至少一名客户")
691	
692	    ids = []
693	    seen_ids = set()
694	    for raw_id in raw_ids:
695	        if isinstance(raw_id, bool) or not isinstance(raw_id, int) or raw_id <= 0:
696	            raise BatchUpdateError("客户编号必须是正整数：%r 不合法" % (raw_id,))
697	        if raw_id not in seen_ids:
698	            seen_ids.add(raw_id)
699	            ids.append(raw_id)
700	
701	    raw_updates = payload.get("updates", {})
702	    if not isinstance(raw_updates, dict):
703	        raise BatchUpdateError("updates 必须是字段修改说明对象")
704	    extra = [key for key in raw_updates if key not in OPTIONAL_FIELDS]
705	    if extra:
706	        raise BatchUpdateError("包含不能修改或不存在的字段：%s" % "、".join(extra))
707	
708	    actions = {}
709	    for field_name in OPTIONAL_FIELDS:
710	        spec = raw_updates.get(field_name, {"op": "keep"})
711	        if not isinstance(spec, dict):
712	            raise BatchUpdateError("%s的修改说明必须是对象" % FIELD_LABELS[field_name])
713	        op = spec.get("op")
714	        if op not in ("keep", "set", "clear"):
715	            raise BatchUpdateError(
716	                "%s的操作必须是 keep、set 或 clear 之一" % FIELD_LABELS[field_name])
717	        if op == "keep":
718	            continue
719	        if op == "clear":
720	            actions[field_name] = None
721	        else:
722	            actions[field_name] = _normalize_set_value(field_name, spec.get("value"))
723	
724	    if not actions:
725	        raise BatchUpdateError("全部字段均保持原值：请至少选择一个字段进行设置或清空")
726	
727	    placeholders = ",".join("?" for _ in ids)
728	    existing = {
729	        row[0]
730	        for row in database.execute(
731	            "SELECT id FROM clients WHERE id IN (%s)" % placeholders, ids
732	        )
733	    }
734	    missing = [cid for cid in ids if cid not in existing]
735	    if missing:
736	        raise BatchUpdateError("找不到对应客户，编号：%s" % "、".join(str(c) for c in missing))
737	
738	    assignments = ", ".join("%s = ?" % field_name for field_name in actions)
739	    params = list(actions.values()) + ids
740	    try:
741	        database.execute(
742	            "UPDATE clients SET %s WHERE id IN (%s)" % (assignments, placeholders), params
743	        )
744	        database.commit()
745	    except sqlite3.DatabaseError:
746	        database.rollback()
747	        raise BatchUpdateError("保存失败：数据库错误，本次修改未生效")
748	
749	    return {"updated_count": len(ids)}
