752	def parse_csv(text):
753	    """解析 RFC 4180 风格 CSV，返回 (header, data_rows)。
754	
755	    支持引号包裹的字段、引号内逗号与换行、双引号转义；
756	    引号外支持 LF / CRLF / CR 换行。结构损坏时抛 FileError：
757	    - 未加引号的字段中出现双引号（双引号只能在字段开头用于包住整个字段）；
758	    - 结束引号后出现逗号、换行或文件结束以外的字符（含空格）；
759	    - 文件结束时仍有字段处于引号内（引号未闭合）。
760	    错误信息区分上述三种情况，并指出发生在表头还是第 N 条数据记录
761	    （数据记录编号不包含表头，引号字段内的换行不增加编号）。
762	    """
763	    rows = []
764	    record = []
765	    field = []
766	    quoted = False        # 当前字段处于引号内
767	    started = False       # 当前字段已经开始（已有内容或已进入引号）
768	    closed = False       # 引号字段刚结束，等待逗号 / 换行 / 文件结束
769	    record_number = 0     # 0 = 表头，1 起为数据记录
770	    i = 0
771	    n = len(text)
772	
773	    def location():
774	        return "表头" if record_number == 0 else "第 %d 条数据记录" % record_number
775	
776	    def structure_error(kind):
777	        raise FileError("CSV 结构损坏（%s）：%s" % (location(), kind))
778	
779	    def finish_record():
780	        nonlocal record, field, started, closed
781	        record.append("".join(field))
782	        rows.append(record)
783	        record = []
784	        field = []
785	        started = False
786	        closed = False
787	
788	    while i < n:
789	        c = text[i]
790	        if quoted:
791	            if c == '"':
792	                if i + 1 < n and text[i + 1] == '"':
793	                    field.append('"')
794	                    i += 2
795	                    continue
796	                quoted = False
797	                closed = True
798	                i += 1
799	                continue
800	            if c == "\r":
801	                # 统一字段内换行符为 LF
802	                if i + 1 < n and text[i + 1] == "\n":
803	                    i += 1
804	                field.append("\n")
805	                i += 1
806	                continue
807	            field.append(c)
808	            i += 1
809	            continue
810	        if closed:
811	            # 引号已结束，只允许逗号、记录换行或文件结束
812	            if c == ",":
813	                record.append("".join(field))
814	                field = []
815	                started = False
816	                closed = False
817	            elif c in "\r\n":
818	                if c == "\r" and i + 1 < n and text[i + 1] == "\n":
819	                    i += 1
